 function derive(u){let p=P(),s=state(u);u.resourceType=p.BASE.resource_type;energy(u,s.energy);u.range=p.BASE.attack_range+(s.tier>=1?p.P.attack_range_bonus_60:0)+(s.tier>=5?p.P.attack_range_bonus_300:0)+(s.mode?p.Q.attack_range_bonus:0);if(s.mode)u.attackSpeed=Math.min(C.maxAttackSpeed,u.attackSpeed*(1+p.Q.attack_speed_bonus_pct));u.skills[0].range=p.Q.cast_range+(s.tier>=5?p.P.q_cast_range_bonus_300:0);u.skills[0].radius=p.Q.explosion_radius+(s.tier>=2?p.P.q_radius_bonus_120:0);u.skills[1].range=p.W.cast_range+(s.tier>=5?p.P.w_cast_range_bonus_300:0);u.skills[1].radius=G.radius(p.W.base_radius,p.W.radius_growth_coefficient,s.fragments);u.skills[2].range=s.tier>=4?p.P.e_range_after_240:p.E.base_teleport_range}
